-- several columns.
--
-- The table list is a static literal (from
-- configuration_variables.DANISH_DEMOCRACY_MODELS_SILVER) so dbt can infer the
-- test's ref() dependencies at parse time; graph.nodes is only populated at run
-- time. Rfam Silver tables are excluded; their keys are tested per model.

{% set silver_ddd_tables = [
    ('silver_ddd_afstemning', 'id'),
    ('silver_ddd_afstemningstype', 'id'),
    ('silver_ddd_aktoer', 'id'),
    ('silver_ddd_aktoertype', 'id'),
