{% for table, key in silver_ddd_tables %}
SELECT '{{ table }}' AS table_name, CAST({{ key }} AS VARCHAR) AS key_value, LKHS_date_valid_from, COUNT(*) AS cnt
FROM {{ ref(table) }}
GROUP BY {{ key }}, LKHS_date_valid_from
HAVING COUNT(*) > 1
    {% if not loop.last %}UNION ALL{% endif %}
{% endfor %}
